it("uses aggregate nouns so an all-one-status label stays grammatical", () => {
  // Regression lock for the bug this label shipped with once: reusing
  // attendeeStatusLabel after a count rendered "4 guests: 4 hasn't responded".
  const attendees = Array.from({ length: 4 }, (_, i) =>
    attendee({
      email: `a${i}@example.com`,
      displayName: `User ${i}`,
      responseStatus: "needsAction",
    }),
  );
  render(<EventAttendeeBadge attendees={attendees} baseColor="#82A0B2" />);
  expect(
    screen.getByRole("img", { name: "4 guests: 4 no response" }),
  ).toBeInTheDocument();
  cleanup();

  // Ordering is most-actionable first, not the enum's needsAction-first order.
  render(
    <EventAttendeeBadge
      attendees={[
        attendee({ email: "n@example.com", responseStatus: "needsAction" }),
        attendee({ email: "a@example.com", responseStatus: "accepted" }),
        attendee({ email: "d@example.com", responseStatus: "declined" }),
      ]}
      baseColor="#82A0B2"
    />,
  );
  expect(
    screen.getByRole("img", {
      name: "3 guests: 1 accepted, 1 declined, 1 no response",
    }),
  ).toBeInTheDocument();
});

